// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/basic.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { createMarkField, markCommands } from "@procedurals/javascript/examples/field-marks/mark-field.js";

function field(p: any, l: Layer) {
  const q = l.params;
  const model = createMarkField(
    l.seed,
    Number(q.columns),
    Number(q.rows),
    Number(q.pitch),
  );
  p.noFill();
  p.strokeWeight(1);
  p.strokeCap(p.ROUND);
  for (const c of markCommands(
    model,
    Number(q.maxLength),
    l.palette,
    Boolean(q.bars),
  )) {
    const color = channels(c.rgb);
    if (c.kind === "segment2" && c.from && c.to) {
      p.stroke(...color, c.opacity8);
      p.line(...c.from, ...c.to);
    } else if (c.vertices) {
      p.noStroke();
      p.fill(...color, c.opacity8);
      p.quad(...c.vertices.flat());
    }
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/basic.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { createPathMarks } from "@procedurals/javascript/examples/path-marks/path-marks.js";

function paths(p: any, l: Layer) {
  const q = l.params,
    model = createPathMarks(l.seed, Number(q.steps), Number(q.distance));
  p.noFill();
  p.strokeWeight(1);
  p.strokeCap(p.ROUND);
  const from = [0, 0],
    to = [0, 0];
  for (let i = 0; i < model.paths.length; i++) {
    const path = model.paths[i];
    p.stroke(...channels(l.palette[i % l.palette.length]), 150);
    for (let step = 0; step < path.steps; step += q.trace ? 1 : 4) {
      path.pointInto(step + 1, to);
      if (q.trace) {
        path.pointInto(step, from);
      } else {
        const a = path.headingAt(step) + Math.PI / 2,
          dx = Math.cos(a) * Number(q.markLength) * 0.5,
          dy = Math.sin(a) * Number(q.markLength) * 0.5;
        from[0] = to[0] - dx;
        from[1] = to[1] - dy;
        to[0] += dx;
        to[1] += dy;
      }
      if (
        Math.max(from[0], to[0]) < -1 ||
        Math.min(from[0], to[0]) > 641 ||
        Math.max(from[1], to[1]) < -1 ||
        Math.min(from[1], to[1]) > 641
      )
        continue;
      p.line(...from, ...to);
    }
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/basic.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { createSeededPlacementMarks, createRadialPlacementMarks, vertexInto } from "@procedurals/javascript/examples/placement-marks/placement-marks.js";

function placements(p: any, l: Layer) {
  const q = l.params,
    model = q.radial
      ? createRadialPlacementMarks(Number(q.separation))
      : createSeededPlacementMarks(
          l.seed,
          Number(q.attempts),
          Number(q.minimum),
          Number(q.maximum),
          Number(q.separation),
        );
  const pt = new Float64Array(2),
    vertices = q.diamonds ? 4 : 64;
  p.noFill();
  p.strokeWeight(1);
  p.strokeCap(p.ROUND);
  p.strokeJoin(p.ROUND);
  for (let i = 0; i < model.placements.size; i++) {
    p.stroke(
      ...channels(
        l.palette[model.placements.sourceIndexAt(i) % l.palette.length],
      ),
    );
    p.beginShape();
    for (let v = 0; v < vertices; v++) {
      vertexInto(model.placements, i, v, Boolean(q.diamonds), pt);
      p.vertex(pt[0], pt[1]);
    }
    p.endShape(p.CLOSE);
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/basic.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { createPathMarks } from "@procedurals/javascript/examples/path-marks/path-marks.js";
import { occupiedLatticePaths2D } from "@procedurals/javascript";
import { cyclicPalette } from "@procedurals/javascript";

function paths(p: any, l: Layer) {
  const q = l.params,
    model = createPathMarks(l.seed, Number(q.steps), Number(q.distance));
  p.noFill();
  p.strokeWeight(1);
  p.strokeCap(p.ROUND);
  const from = [0, 0],
    to = [0, 0];
  for (let i = 0; i < model.paths.length; i++) {
    const path = model.paths[i];
    p.stroke(...channels(l.palette[i % l.palette.length]), 150);
    for (let step = 0; step < path.steps; step += q.trace ? 1 : 4) {
      path.pointInto(step + 1, to);
      if (q.trace) {
        path.pointInto(step, from);
      } else {
        const a = path.headingAt(step) + Math.PI / 2,
          dx = Math.cos(a) * Number(q.markLength) * 0.5,
          dy = Math.sin(a) * Number(q.markLength) * 0.5;
        from[0] = to[0] - dx;
        from[1] = to[1] - dy;
        to[0] += dx;
        to[1] += dy;
      }
      if (
        Math.max(from[0], to[0]) < -1 ||
        Math.min(from[0], to[0]) > 641 ||
        Math.max(from[1], to[1]) < -1 ||
        Math.min(from[1], to[1]) > 641
      )
        continue;
      p.line(...from, ...to);
    }
  }
}

function lattice(p: any, l: Layer) {
  const q = l.params,
    count = Number(q.count),
    steps = Number(q.steps);
  const starts = Array.from({ length: count }, (_, i) => {
    const s = (13 * i) % 36;
    return [2 + 4 * (s % 6), 2 + 4 * Math.floor(s / 6)];
  });
  const paths = occupiedLatticePaths2D({
    dimensions: [24, 24],
    starts,
    maxSteps: steps,
    maxCells: count * (steps + 1),
    random: { seed: l.seed },
  });
  const palette = cyclicPalette({ colors: l.palette });
  const pixel = (x: number) => 44 + 24 * x;
  if (q.grid) {
    p.stroke(205, 200, 190);
    p.strokeWeight(1);
    for (let i = 0; i <= 24; i++) {
      p.line(32, 32 + 24 * i, 608, 32 + 24 * i);
      p.line(32 + 24 * i, 32, 32 + 24 * i, 608);
    }
  }
  p.strokeCap(p.ROUND);
  p.strokeJoin(p.ROUND);
  for (let i = 0; i < paths.pathCount; i++) {
    const n = paths.pathLengthAt(i);
    if (!n) continue;
    const col = palette.sample(i * 0.173);
    if (q.dots) {
      p.noStroke();
      p.fill(...channels(col));
      for (let j = 0; j < n; j++) {
        const [x, y] = paths.cellAt(i, j);
        p.circle(pixel(x), pixel(y), q.dotSize);
      }
      continue;
    }
    p.strokeWeight(q.weight);
    for (const offset of [3, 0]) {
      p.stroke(...(offset ? [30, 30, 30, 70] : channels(col)));
      for (let j = 1; j < n; j++) {
        const a = paths.cellAt(i, j - 1),
          b = paths.cellAt(i, j);
        p.line(
          pixel(a[0]) + offset,
          pixel(a[1]) + offset,
          pixel(b[0]) + offset,
          pixel(b[1]) + offset,
        );
      }
    }
    p.stroke(...channels(col));
    p.strokeWeight(2);
    p.fill(255, 250, 230);
    for (const j of n > 1 ? [0, n - 1] : [0]) {
      const a = paths.cellAt(i, j);
      p.circle(pixel(a[0]), pixel(a[1]), 8);
    }
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/geometry.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { noiseBandPath2D } from "@procedurals/javascript";

type Q = Record<string, any>;

const colors = (layer: Layer): number[] => layer.palette;

const colour = (p: any, value: number, alpha = 255) =>
  p.stroke(...channels(value), alpha);

const pick = (palette: number[], index: number) =>
  palette[index % palette.length];

function band(p: any, l: Layer) {
  const q = l.params as Q,
    palette = colors(l);
  p.noFill();
  p.strokeWeight(q.weight);
  for (let i = 0; i < q.count; i++) {
    const path = noiseBandPath2D({
      field: { seed: (l.seed + 17) >>> 0 },
      start: [40 + 80 * (i % 8), 40 + 80 * Math.floor(i / 8)],
      heading: 0,
      seed: (l.seed + i) >>> 0,
      attempts: 700,
      stepDistance: 1,
      fieldScale: q.fieldScale,
      fieldOffset: [7.3, 11.7],
      tolerance: q.tolerance,
      maxVertices: 701,
    });
    const a = [0, 0],
      b = [0, 0];
    colour(p, pick(palette, i), 150);
    for (let j = 1; j < path.size; j += q.ticks ? 8 : 1) {
      path.pointInto(j, a);
      if (q.ticks) {
        const h = path.headingAt(j - 1),
          dx = -Math.sin(h) * 3,
          dy = Math.cos(h) * 3;
        p.line(a[0] - dx, a[1] - dy, a[0] + dx, a[1] + dy);
      } else {
        path.pointInto(j - 1, b);
        p.line(b[0], b[1], a[0], a[1]);
      }
    }
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/geometry.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { seededEndpointBranches2D } from "@procedurals/javascript";
import { seededCirclePlacement2D } from "@procedurals/javascript";

type Q = Record<string, any>;

const colors = (layer: Layer): number[] => layer.palette;

const colour = (p: any, value: number, alpha = 255) =>
  p.stroke(...channels(value), alpha);

const fill = (p: any, value: number, alpha = 255) =>
  p.fill(...channels(value), alpha);

const pick = (palette: number[], index: number) =>
  palette[index % palette.length];

function branch(p: any, l: Layer) {
  const q = l.params as Q,
    rules: any[] = [];
  for (let g = 0; g < q.generations; g++) {
    const spread = q.binary ? 0.12 : 0.5;
    const probability = q.binary ? 0.8 : 0.7;
    const row: any[] = [
      { probability, turn: [-spread, -spread * 0.5] },
      { probability, turn: [spread * 0.5, spread] },
    ];
    if (!q.binary)
      row.push({ probability: 0.4, turn: [-spread * 0.2, spread * 0.2] });
    rules.push({ lengthScale: [0.65, 0.85], slots: row });
  }
  const roots = q.forest
      ? seededCirclePlacement2D({
          seed: l.seed,
          attempts: 6,
          origin: [90, 260],
          extent: [460, 280],
          radiusRange: [28, 42],
          separationScale: 1,
        })
      : null,
    trees: any[] = [];
  if (roots) {
    const pt = new Float64Array(2);
    for (let i = 0; i < roots.size; i++) {
      roots.pointInto(i, pt);
      trees.push(
        seededEndpointBranches2D({
          seed: (l.seed + i) >>> 0,
          root: {
            origin: [pt[0], pt[1]],
            heading: -Math.PI / 2,
            length: roots.radiusAt(i),
          },
          rules,
          maxSegments: 10000,
        }),
      );
    }
  } else
    trees.push(
      seededEndpointBranches2D({
        seed: l.seed,
        root: { origin: [320, 590], heading: -Math.PI / 2, length: 105 },
        rules,
        maxSegments: 10000,
      }),
    );
  const palette = colors(l),
    s = new Float64Array(4);
  p.noFill();
  p.strokeCap(p.ROUND);
  for (const tree of trees)
    for (let i = 0; i < tree.size; i++) {
      tree.segmentInto(i, s);
      colour(p, pick(palette, Math.floor(tree.generationAt(i) / 2)));
      p.strokeWeight(Math.max(0.2, (q.weight * tree.lengthAt(i)) / 100));
      p.line(s[0], s[1], s[2], s[3]);
      if (q.tipSize && tree.childCountAt(i) === 0) {
        p.noStroke();
        fill(p, pick(palette, palette.length - 1));
        p.circle(s[2], s[3], q.tipSize);
      }
    }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/geometry.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { seededLinePool2D } from "@procedurals/javascript";

type Q = Record<string, any>;

const colors = (layer: Layer): number[] => layer.palette;

const colour = (p: any, value: number, alpha = 255) =>
  p.stroke(...channels(value), alpha);

const pick = (palette: number[], index: number) =>
  palette[index % palette.length];

function cutBranch(p: any, l: Layer) {
  const q = l.params as Q,
    pool = seededLinePool2D({
      seed: l.seed,
      segment: [120, 620, 520, 120],
      attempts: q.attempts,
      firstCutAngleScale: q.angle,
      minCutLength: 4,
      maxSegments: q.attempts * 2 + 1,
    }),
    s = [0, 0, 0, 0];
  p.noFill();
  p.strokeWeight(q.weight);
  colour(p, pick(colors(l), 0), q.opacity);
  for (let i = 0; i < pool.size; i++) {
    pool.segmentInto(i, s);
    p.line(s[0], s[1], s[2], s[3]);
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/loop-marks-quality.ts.

import type { Layer } from "../studio-types";
import { closedSpline2D } from "@procedurals/javascript"

const WORK_LIMIT = 12_000;

function number(params: Params, key: string, min: number, max: number, integer = false): number {
  const value = params[key];
  if (typeof value !== "number" || !Number.isFinite(value) || value < min || value > max ||
      (integer && !Number.isInteger(value)))
    throw new Error(`${key} must be ${integer ? "an integer" : "a finite number"} between ${min} and ${max}`);
  return value;
}

function member<T extends string>(params: Params, key: string, values: readonly T[]): T {
  const value = params[key];
  if (!values.includes(value as T)) throw new Error(`${key} must be one of ${values.join(", ")}`);
  return value as T;
}

function options(params: Params) {
  const layout = member(params, "layout", ["row", "grid", "nested"] as const);
  const treatment = member(params, "treatment", ["outline", "tiles", "fans", "outline-tiles"] as const);
  const tileShape = member(params, "tileShape", ["bar", "diamond", "tick"] as const);
  return {
    layout, treatment, tileShape,
    loopCount: number(params, "loopCount", 1, 16, true),
    columns: number(params, "columns", 1, 8, true),
    spacingX: number(params, "spacingX", 10, 500),
    spacingY: number(params, "spacingY", 10, 500),
    centerX: number(params, "centerX", -320, 960),
    centerY: number(params, "centerY", -320, 960),
    radiusX: number(params, "radiusX", 4, 500),
    radiusY: number(params, "radiusY", 4, 500),
    nestedScale: number(params, "nestedScale", .2, 1),
    knotCount: number(params, "knotCount", 5, 16, true),
    lobes: number(params, "lobes", 0, 12, true),
    lobeDepth: number(params, "lobeDepth", 0, .8),
    phase: number(params, "phase", -180, 180),
    subdivisions: number(params, "subdivisions", 8, 64, true),
    tileSpacing: number(params, "tileSpacing", 4, 80),
    tileWidth: number(params, "tileWidth", 1, 80),
    tileHeight: number(params, "tileHeight", 1, 80),
    outlineWeight: number(params, "outlineWeight", .1, 12),
    fanOpacity: number(params, "fanOpacity", 0, 255),
  };
}

function centerAt(q: ReturnType<typeof options>, index: number): [Point, number] {
  if (q.layout === "row")
    return [[q.centerX + (index - (q.loopCount - 1) / 2) * q.spacingX,
      q.centerY + (index - (q.loopCount - 1) / 2) * q.spacingY], 1];
  if (q.layout === "nested") return [[q.centerX, q.centerY], q.nestedScale ** index];
  const row = Math.floor(index / q.columns), rowStart = row * q.columns;
  const rowCount = Math.min(q.columns, q.loopCount - rowStart);
  const column = index - rowStart, rows = Math.ceil(q.loopCount / q.columns);
  return [[q.centerX + (column - (rowCount - 1) / 2) * q.spacingX,
    q.centerY + (row - (rows - 1) / 2) * q.spacingY], 1];
}

function buildLoopMarks(params: Params): { loops: LoopRecord[]; tileCounts: number[]; work: number } {
  const q = options(params), loops: LoopRecord[] = [], tileCounts: number[] = [];
  const sampleCount = q.knotCount * q.subdivisions;
  const drawsOutline = q.treatment === "outline" || q.treatment === "outline-tiles";
  const drawsTiles = q.treatment === "tiles" || q.treatment === "outline-tiles";
  const drawsFans = q.treatment === "fans";
  let work = q.loopCount * sampleCount * (1 + Number(drawsOutline) + Number(drawsFans));
  if (work > WORK_LIMIT) throw new Error("Loop marks sampled-contour work budget exceeded");
  for (let index = 0; index < q.loopCount; index++) {
    const [center, scale] = centerAt(q, index), [cx, cy] = center;
    const controls: Point[] = Array.from({ length: q.knotCount }, (_, knot) => {
      const angle = 2 * Math.PI * knot / q.knotCount;
      return [cx + q.radiusX * scale * Math.cos(angle), cy + q.radiusY * scale * Math.sin(angle)];
    });
    const spline = closedSpline2D({ controls, subdivisions: q.subdivisions });
    const points: Point[] = Array.from({ length: sampleCount }, (_, sample) => {
      const base = spline.sampleParameter(sample / q.subdivisions);
      const angle = 2 * Math.PI * sample / sampleCount;
      const modulation = q.lobes === 0 ? 1 :
        1 + q.lobeDepth * Math.cos(q.lobes * angle + q.phase * Math.PI / 180 + index * 2 * Math.PI / q.loopCount);
      return [cx + (base.x - cx) * modulation, cy + (base.y - cy) * modulation];
    });
    const cumulative = [0];
    for (let sample = 0; sample < sampleCount; sample++) {
      const a = points[sample], b = points[(sample + 1) % sampleCount];
      cumulative.push(cumulative[sample] + Math.hypot(b[0] - a[0], b[1] - a[1]));
    }
    const length = cumulative[sampleCount];
    const tileCount = drawsTiles && length > 0 ? Math.ceil(length / q.tileSpacing) : 0;
    work += tileCount * 4;
    if (work > WORK_LIMIT) throw new Error("Loop marks tile/fan work budget exceeded");
    loops.push({ center, points, length, cumulative });
    tileCounts.push(tileCount);
  }
  return { loops, tileCounts, work };
}

function colour(p: any, layer: Layer, index: number, alpha: number, kind: "stroke" | "fill") {
  const rgb = layer.palette[((index % layer.palette.length) + layer.palette.length) % layer.palette.length] >>> 0;
  p[kind]((rgb >>> 16) & 255, (rgb >>> 8) & 255, rgb & 255, alpha);
}

function tileAt(loop: LoopRecord, distance: number): { point: Point; tangent: Point; normal: Point } {
  const { points, cumulative } = loop;
  let low = 0, high = points.length;
  while (low + 1 < high) {
    const mid = (low + high) >>> 1;
    if (cumulative[mid] <= distance) low = mid; else high = mid;
  }
  const a = points[low], b = points[(low + 1) % points.length];
  const length = cumulative[low + 1] - cumulative[low];
  const t = length > 0 ? (distance - cumulative[low]) / length : 0;
  const tx = length > 0 ? (b[0] - a[0]) / length : 1;
  const ty = length > 0 ? (b[1] - a[1]) / length : 0;
  return { point: [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t],
    tangent: [tx, ty], normal: [-ty, tx] };
}

function polygon(p: any, vertices: Point[]) {
  p.beginShape();
  for (const vertex of vertices) p.vertex(vertex[0], vertex[1]);
  p.endShape(p.CLOSE);
}

function drawLoopMarksModern(p: any, layer: Layer): void {
  const q = options(layer.params), { loops, tileCounts } = buildLoopMarks(layer.params);
  const drawsOutline = q.treatment === "outline" || q.treatment === "outline-tiles";
  const drawsTiles = q.treatment === "tiles" || q.treatment === "outline-tiles";
  for (let index = 0; index < loops.length; index++) {
    const loop = loops[index], points = loop.points;
    if (q.treatment === "fans") {
      p.noStroke();
      for (let sample = 0; sample < points.length; sample++) {
        colour(p, layer, index + Math.floor(sample / Math.max(1, q.subdivisions)), q.fanOpacity, "fill");
        const a = points[sample], b = points[(sample + 1) % points.length];
        p.triangle(loop.center[0], loop.center[1], a[0], a[1], b[0], b[1]);
      }
    }
    if (drawsOutline) {
      p.noFill(); p.strokeWeight(q.outlineWeight); colour(p, layer, index, 220, "stroke");
      for (let sample = 0; sample < points.length; sample++) {
        const a = points[sample], b = points[(sample + 1) % points.length];
        p.line(a[0], a[1], b[0], b[1]);
      }
    }
    if (drawsTiles) {
      for (let tile = 0; tile < tileCounts[index]; tile++) {
        const { point: [x, y], tangent: [tx, ty], normal: [nx, ny] } = tileAt(loop, tile * q.tileSpacing);
        colour(p, layer, index + tile, 235, q.tileShape === "tick" ? "stroke" : "fill");
        if (q.tileShape === "tick") {
          p.strokeWeight(q.tileWidth);
          p.line(x - nx * q.tileHeight / 2, y - ny * q.tileHeight / 2,
            x + nx * q.tileHeight / 2, y + ny * q.tileHeight / 2);
        } else {
          p.noStroke();
          const w = q.tileWidth / 2, h = q.tileHeight / 2;
          const v = (u: number, v: number): Point => [x + tx * u + nx * v, y + ty * u + ny * v];
          polygon(p, q.tileShape === "bar" ? [v(-w, -h), v(w, -h), v(w, h), v(-w, h)] :
            [v(0, -h), v(w, 0), v(0, h), v(-w, 0)]);
        }
      }
    }
  }
}

// Actual app drawing code. p is a p5 graphics buffer; layer contains the controls, seed and palette.
// Imports are relative to apps/web/lib/adapters/geometry.ts.

import type { Layer } from "../studio-types";
import { channels } from "./types";
import { seededQuadrantPartition2D } from "@procedurals/javascript";

type Q = Record<string, any>;

const colors = (layer: Layer): number[] => layer.palette;

const fill = (p: any, value: number, alpha = 255) =>
  p.fill(...channels(value), alpha);

const pick = (palette: number[], index: number) =>
  palette[index % palette.length];

function regions(p: any, l: Layer) {
  const q = l.params as Q,
    model = seededQuadrantPartition2D({
      seed: l.seed,
      replacements: q.replacements,
      origin: [0, 0],
      extent: [640, 640],
      selectionFraction: q.fraction,
    }),
    b = new Float64Array(4),
    pt = new Float64Array(2),
    palette = colors(l);
  p.noStroke();
  for (let i = 0; i < model.size; i++) {
