    const sampled = resamplePolyline2D({ points, closed: true, count: q.beads, maxWork: 1000 });
    if (q.thread) {
      p.noFill();
      p.stroke(...palette(layer, orbit), 95);
      p.strokeWeight(0.65);
      polygon(p, points);
