const q=(l)=>l.params, colors=(l)=>l.packedRGBpalette||l.palette||[0x222222], c=(p,v,a=255)=>p.stroke((v>>>16)&255,(v>>>8)&255,v&255,a), f=(p,v,a=255)=>p.fill((v>>>16)&255,(v>>>8)&255,v&255,a);

