import type { Layer } from "../studio-types";
import { CANVAS, panelLayout } from "@procedurals/javascript/examples/motif-compositions/compositions.js";
import { shapeMatrixRecords } from "@procedurals/javascript/examples/motif-compositions/field-records.js";
